import z from "zod/v4";
export const PortfolioChartPnlItemSchema = z.object({
    timestamp: z.number(),
    data_points: z.number(),
    vault_equity: z
        .number()
        .nullable()
        .optional()
        .transform((v) => v ?? 0),
    // Spot holdings value at this snapshot. NOT included in data_points (the
    // canonical perp Portfolio Value); the "Perps + Spot" cut is
    // data_points + spot_value. Absent for the pnl type and on pre-spot
    // servers; 0 for history predating the spot recorder.
    spot_value: z
        .number()
        .nullable()
        .optional()
        .transform((v) => v ?? 0),
    // Spot PnL (unrealized + realized) at this snapshot. Sidecar for the same
    // reason as spot_value: the combined cut is data_points + spot_pnl. Absent
    // for the account_value type and on pre-spot-PnL servers; 0 for history
    // predating the spot PnL columns.
    spot_pnl: z
        .number()
        .nullable()
        .optional()
        .transform((v) => v ?? 0),
});
export const PortfolioChartSchema = z.array(PortfolioChartPnlItemSchema);
